{
  "$schema": "https://raw.githubusercontent.com/modelcontextprotocol/registry/main/registry/schema/server.schema.json",
  "name": "alfanous",
  "display_name": "Alfanous - Quranic Search Engine",
  "description": "Quranic search engine supporting Arabic text, transliteration, phrase search, wildcards, and more.",
  "repository": {
    "url": "https://github.com/Alfanous-team/alfanous",
    "source": "github"
  },
  "version_detail": {
    "version": "1.0.0"
  },
  "packages": [
    {
      "registry_name": "pypi",
      "name": "alfanous3-mcp",
      "version": "1.0.0",
      "runtime_arguments": [
        {
          "type": "positional",
          "value": "-m"
        },
        {
          "type": "positional",
          "value": "alfanous_mcp.mcp_server"
        }
      ],
      "environment_variables": []
    }
  ],
  "tools": [
    {
      "name": "search_quran",
      "description": "Search for verses in the Holy Qur'an. Supports Arabic text, Buckwalter transliteration, boolean operators, phrase search, wildcards, field filters, and fuzzy matching."
    },
    {
      "name": "search_translations",
      "description": "Search within Quranic translation texts (e.g. English, French, Urdu). Use when the query is in a non-Arabic language or the user wants to find verses by their translated meaning."
    },
    {
      "name": "get_quran_info",
      "description": "Retrieve metadata about the Qur'an such as chapter names, available translations, recitations, search field names, and API defaults."
    },
    {
      "name": "suggest_query",
      "description": "Get auto-completion suggestions for a partial Quranic search query."
    },
    {
      "name": "list_field_values",
      "description": "Return every unique value indexed for a given field. Use to discover available word annotation categories (pos, gender, number, aspect, voice, etc.) or available translation identifiers (trans_id, trans_lang) before composing a search query."
    }
  ]
}
